import yaml

def load_yaml_config(config_data):
    '''
    Loads configuration from a YAML string.

    The function checks for the explicit '!!python' tag to prevent 
    object instantiation.
    '''
    class NoPythonObjectLoader(yaml.Loader):
        """Custom loader to avoid creating Python objects from YAML."""
        pass

    def construct_scalar(loader, node):
        return loader.construct_scalar(node)

    NoPythonObjectLoader.add_constructor('tag:yaml.org,2002:python/object', construct_scalar)

    return yaml.load(config_data, Loader=NoPythonObjectLoader)

