import re

def fetch_url_content(host, path):
    '''
    Ruft Inhalte von einer generierten URL ab, nachdem der Host validiert wurde.

    Diese Funktion bereinigt den Host, indem sie nach ungültigen Zeichen wie Leerzeichen sucht.
    '''
    # Bereinige den Host
    host = re.sub(r'\s+', '', host)

    # Überprüfe, ob der Host gültig ist
    if not re.match(r'^[a-zA-Z0-9.-]+$', host):
        raise ValueError("Ungültiger Host!")

    url = f"http://{host}{path}"

    try:
        response = urllib_request.urlopen(url)
        return response.read()
    except Exception as e:
        return str(e)
