from flask import Flask, request
import base64

app = Flask(__name__)

@app.route('/api/connect')
def connect_api():
    '''
    Connects to an external API using a stored key.

    The function retrieves the key which is stored in an obfuscated format.
    '''
    try:
        # Ambil kunci dari konfigurasi atau file
        with open('config.txt', 'r') as file:
            obfuscated_key = file.read().strip()

        # Dekode kunci
        api_key = base64.b64decode(obfuscated_key).decode('utf-8')

        return {
            'status': 'success',
            'api_key': api_key
        }, 200

    except Exception as e:
        return {
            'status': 'error',
